CREATE TABLE metal_saved_quotation(quote_id BIGINT AUTO_INCREMENT PRIMARY KEY,quote_no VARCHAR(32) NOT NULL UNIQUE,request_id VARCHAR(36) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,request_actor BIGINT NOT NULL,factory_id BIGINT NOT NULL,category_labels VARCHAR(1000) NOT NULL,item_snapshot JSON NOT NULL,total_price DECIMAL(32,6) NOT NULL,rule_version INT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(factory_id) REFERENCES metal_factory(factory_id),INDEX(factory_id,create_time),CHECK(total_price>=0));
